+    cmd.joint_cmd[3 * leg_side + 2].torque =
+        80 * (goal_angle[2] -
+              data.joint_data.joint_data[3 * leg_side + 2].position) +
+        0.7 * (goal_velocity[2] -
+               data.joint_data.joint_data[3 * leg_side + 2].velocity);
+  }
+}

