+    if (!server || port < 0 || port > 65535) {
+        if (onError) {
+            onError(EINVAL, "Invalid server or port number.");
+        }
+        return;
+    }
+
+    server->impl->Bind(
+        port,
+        [onError](int errorCode, std::string errorMessage) {
+            if (onError) {
+                onError(errorCode, errorMessage.c_str());
+            }
+        }
